::v-deep .confirmClass {
  padding-bottom: 15px;

  .el-message-box__status {
    position: absolute;
    top: 21%;
  }

  .el-message-box__message {
    font-size: 16px;
    font-weight: bold;

    div {
      font-size: 14px;
      margin-top: 10px;
      font-weight: normal;
    }
  }

  .el-button--primary {
    color: #FFF;
    background-color: #f56c6c;
    border-color: #f56c6c;
  }

  .el-button--primary:focus, .el-button--primary:hover {
    background: #f78989;
    border-color: #f78989;
    color: #FFF;
  }
}
